import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { getDoctorById } from "../services/doctorService";
import { getBookedSlots, bookAppointment } from "../services/appointmentService";
import { isLoggedIn } from "../utils/auth";

function BookAppointment() {
  const { doctorId } = useParams();
  const navigate = useNavigate();

  const [doctor, setDoctor] = useState(null);
  const [selectedDate, setSelectedDate] = useState("");
  const [selectedTime, setSelectedTime] = useState("");
  const [bookedSlots, setBookedSlots] = useState([]);

  // ✅ FETCH DOCTOR
  useEffect(() => {
    fetchDoctor();
  }, [doctorId]);

  const fetchDoctor = async () => {
    try {
      const res = await getDoctorById(doctorId);
      setDoctor(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  // ✅ FETCH BOOKED SLOTS
  useEffect(() => {
    if (selectedDate) {
      fetchBookedSlots();
    }
  }, [selectedDate]);

  const fetchBookedSlots = async () => {
    try {
      const res = await getBookedSlots(doctorId, selectedDate);
      setBookedSlots(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  // 🔥 GENERATE DYNAMIC SLOTS (10 min)
  const generateTimeSlots = (startTime, endTime) => {
    const slots = [];
    if (!startTime || !endTime) return slots;

    let start = new Date(`1970-01-01T${startTime}`);
    let end = new Date(`1970-01-01T${endTime}`);

    while (start <= end) {
      const hours = String(start.getHours()).padStart(2, "0");
      const minutes = String(start.getMinutes()).padStart(2, "0");

      slots.push(`${hours}:${minutes}`);
      start.setMinutes(start.getMinutes() + 30);
    }

    return slots;
  };

  // 🔥 DISABLE PAST TIME
  const isPastTime = (date, time) => {
    if (!date) return false;

    const selectedDateTime = new Date(`${date}T${time}`);
    const now = new Date();

    return selectedDateTime < now;
  };

  const timeSlots = generateTimeSlots(
    doctor?.availableFrom,
    doctor?.availableTo
  );

  // ✅ BOOK APPOINTMENT
  const handleBooking = async () => {
    if (!isLoggedIn()) {
      alert("Please login first");
      navigate("/login");
      return;
    }

    if (!selectedDate || !selectedTime) {
      alert("Select date & time");
      return;
    }

    try {
      const payload = {
        userId: 1, // ⚠️ replace later with logged user
        doctorId: Number(doctorId),
        appointmentDate: selectedDate,
        timeSlot: selectedTime,
      };

      await bookAppointment(payload);

      alert("Booking Successful ✅");

      setSelectedTime("");
      fetchBookedSlots(); // refresh

    } catch (err) {
      console.error(err);
      alert(err.response?.data?.message || "Booking failed ❌");
    }
  };

  if (!doctor) return <h3>Loading...</h3>;

  return (
    <div style={styles.container}>
      {/* Doctor Info */}
      <div style={styles.card}>
        <img src={doctor.image} alt="doctor" style={styles.image} />
        <h2>{doctor.name}</h2>
        <p>{doctor.specialization}</p>
      </div>

      {/* Booking */}
      <div style={styles.booking}>
        <h3>Select Date</h3>
        <input
          type="date"
          onChange={(e) => setSelectedDate(e.target.value)}
        />

        <h3>Select Time</h3>
        <div style={styles.slots}>
          {timeSlots.map((time) => {
            const isBooked = bookedSlots.includes(time);
            const isPast = isPastTime(selectedDate, time);

            return (
              <button
                key={time}
                disabled={isBooked || isPast}
                style={
                  isBooked
                    ? styles.disabledSlot
                    : isPast
                    ? styles.pastSlot
                    : selectedTime === time
                    ? styles.selectedSlot
                    : styles.slot
                }
                onClick={() => {
                  if (!isBooked && !isPast) {
                    setSelectedTime(time);
                  }
                }}
              >
                {time}
              </button>
            );
          })}
        </div>

        <button style={styles.bookBtn} onClick={handleBooking}>
          Confirm Booking
        </button>
      </div>
    </div>
  );
}

const styles = {
  container: {
    padding: "20px",
  },
  card: {
    textAlign: "center",
    marginBottom: "20px",
  },
  image: {
    width: "100px",
    borderRadius: "50%",
  },
  booking: {
    textAlign: "center",
  },
  slots: {
    display: "flex",
    justifyContent: "center",
    gap: "10px",
    flexWrap: "wrap",
    margin: "10px 0",
  },
  slot: {
    padding: "8px 12px",
    border: "1px solid #1976d2",
    background: "#fff",
    cursor: "pointer",
    borderRadius: "5px",
  },
  selectedSlot: {
    padding: "8px 12px",
    border: "1px solid #1976d2",
    background: "#1976d2",
    color: "#fff",
    cursor: "pointer",
    borderRadius: "5px",
  },
  disabledSlot: {
    padding: "8px 12px",
    border: "1px solid #ccc",
    background: "#ccc",
    color: "#666",
    cursor: "not-allowed",
    borderRadius: "5px",
  },
  pastSlot: {
    padding: "8px 12px",
    border: "1px solid #ddd",
    background: "#eee",
    color: "#999",
    cursor: "not-allowed",
    borderRadius: "5px",
  },
  bookBtn: {
    marginTop: "15px",
    padding: "10px 20px",
    background: "green",
    color: "#fff",
    border: "none",
    borderRadius: "5px",
    cursor: "pointer",
  },
};

export default BookAppointment;
